import{_ as e,o as i,c as o,a2 as r}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Index of Legal Provisions","description":"","frontmatter":{},"headers":[],"relativePath":"en/92-法律条文索引.md","filePath":"en/92-法律条文索引.md","lastUpdated":null}'),a={name:"en/92-法律条文索引.md"};function s(n,t,l,d,c,h){return i(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="index-of-legal-provisions" tabindex="-1">Index of Legal Provisions <a class="header-anchor" href="#index-of-legal-provisions" aria-label="Permalink to &quot;Index of Legal Provisions&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Item</th><th>Content</th></tr></thead><tbody><tr><td>Document Number</td><td>92</td></tr><tr><td>Module</td><td>Appendices and Reference Materials</td></tr><tr><td>Core Keywords</td><td>legal index, Symbiosis Constitution, labor law, consumer protection law, supporting laws</td></tr></tbody></table><h2 id="i-index-description" tabindex="-1">I. Index Description <a class="header-anchor" href="#i-index-description" aria-label="Permalink to &quot;I. Index Description&quot;">​</a></h2><p>This index contains the major currently effective legal documents and their core provisions of the Anker Symbiosis Civilization, organized by legal hierarchy and department. The scope of the index covers the &quot;Symbiosis Constitution&quot;, &quot;Symbiosis Labor Law&quot;, &quot;Consumer Protection Law&quot;, as well as five supporting laws on education, medical care, housing, environment, and antitrust. Each index entry lists the legal name, provision number, and a summary of the core content of the provision. This index is a reference tool; for the complete text of legal provisions and judicial interpretations, please refer to the official text of each law.</p><h2 id="ii-symbiosis-constitution" tabindex="-1">II. Symbiosis Constitution <a class="header-anchor" href="#ii-symbiosis-constitution" aria-label="Permalink to &quot;II. Symbiosis Constitution&quot;">​</a></h2><p>The &quot;Symbiosis Constitution&quot; is the fundamental law of the Anker Symbiosis Civilization, with the highest legal effect, enacted upon the formal establishment of the symbiosis civilization.</p><table tabindex="0"><thead><tr><th>Provision Number</th><th>Core Content</th></tr></thead><tbody><tr><td>Article 1</td><td>Establishes Hengyuanzhou (Wanling Hengmao Origin Universe) as the governance domain of the Anker Symbiosis Civilization; the fundamental purpose of the symbiosis civilization is to achieve symbiosis of all races and cosmic dimension elevation</td></tr><tr><td>Article 2</td><td>Establishes anti-plunderism as the fundamental stance of the civilization; prohibits any form of plunder-style cultivation and resource plunder</td></tr><tr><td>Article 3</td><td>Establishes &quot;returning the right to choose destiny and evolution to all sentient beings&quot; as the core concept of the civilization</td></tr><tr><td>Article 4</td><td>Establishes more work more gain, self-growth, everyone has a path, all races progress together as the basic policies of the civilization</td></tr><tr><td>Article 5</td><td>Establishes the free opening system of three hundred sets of origin cultivation systems; no organization or individual may monopolize the authorization to transmit cultivation systems</td></tr><tr><td>Article 6</td><td>Establishes the joint production contract mechanism as the basic resource allocation system</td></tr><tr><td>Article 7</td><td>Establishes the 20% activation strategy as a phased national goal</td></tr><tr><td>Article 8</td><td>Establishes the reality-based principle; the real world is the only real world, fictional settings have no legal effect</td></tr><tr><td>Article 9</td><td>Establishes the four-stage dimension elevation path as the long-term development strategy of the civilization</td></tr><tr><td>Article 10</td><td>Establishes the principle of equality of all races; all life forms are equal before the law</td></tr><tr><td>Article 11</td><td>Establishes the principle of symbiotic evolution; individual evolution may not come at the expense of damaging the evolutionary rights of other individuals or collectives</td></tr><tr><td>Article 12</td><td>Establishes the principle of more work more gain; resource allocation takes contribution as the core basis</td></tr><tr><td>Article 13</td><td>Establishes the principle of self-growth; respects each life&#39;s autonomous right to choose evolution</td></tr><tr><td>Article 14</td><td>Establishes the principle that everyone has a path; the state has the obligation to provide each life with a basic evolutionary path and resource guarantee</td></tr><tr><td>Article 15</td><td>Establishes the sustainability principle; all development must take into account the sustainability of the cosmic origin</td></tr><tr><td>Articles 16-25</td><td>Stipulate the basic rights of all sentient beings: right to choose evolution, right to obtain cultivation resources, right to equal protection, right to symbiotic participation, right to cultural preservation, right to relief and appeal, right to personal freedom, right to human dignity, right to freedom of belief, right to freedom of expression</td></tr><tr><td>Articles 26-31</td><td>Stipulate the basic obligations of all sentient beings: obligation to abide by the law, obligation to maintain symbiotic order, obligation to labor contribution, obligation to protect the environment, obligation to respect the rights of others, obligation to guide junior cultivators</td></tr><tr><td>Article 32</td><td>Establishes the Anker Council as the highest authority, composed of representatives of all races in proportion</td></tr><tr><td>Article 33</td><td>Establishes the Symbiosis Executive Committee as the highest administrative organ</td></tr><tr><td>Article 34</td><td>Establishes the Symbiosis Court as the highest judicial organ, independently exercising judicial power</td></tr><tr><td>Article 35</td><td>Establishes the Anker Supervisory Committee as an independent supervisory organ</td></tr><tr><td>Article 36</td><td>Stipulates the legislative procedure: bills are passed by a majority of more than half of the Anker Council</td></tr><tr><td>Article 37</td><td>Stipulates the constitutional amendment procedure: must be passed by a majority of more than two-thirds of the Anker Council and approved by more than half of the national referendum</td></tr><tr><td>Article 38</td><td>Establishes the constitutional review system; the Symbiosis Court has the right to declare laws that violate the Constitution invalid</td></tr><tr><td>Article 39</td><td>Establishes the constitutional litigation system; all sentient beings may directly initiate litigation based on the Constitution</td></tr><tr><td>Article 40</td><td>Stipulates the local autonomy system; each star domain and each plane implements autonomy within the constitutional framework</td></tr><tr><td>Article 41</td><td>Establishes the republican system of all races; all ethnic groups are equal in the symbiosis civilization and implement regional autonomy</td></tr><tr><td>Article 42</td><td>Stipulates the economic system of the symbiosis civilization: based on joint production contracts, multiple ownership economies develop together</td></tr><tr><td>Article 43</td><td>Stipulates the state ownership and fair distribution system of cultivation resources</td></tr><tr><td>Article 44</td><td>Establishes the education equity system, guaranteeing each life&#39;s equal right to education</td></tr><tr><td>Article 45</td><td>Establishes the universal medical security system</td></tr><tr><td>Article 46</td><td>Establishes the housing security system, guaranteeing each life&#39;s basic right to housing</td></tr><tr><td>Article 47</td><td>Stipulates the basic principles of cross-plane interaction; no unauthorized cross-plane travel without permission</td></tr><tr><td>Article 48</td><td>Stipulates that the legitimate output of archaeological activities is limited to abstract knowledge and information; the return of matter and energy is prohibited</td></tr><tr><td>Article 49</td><td>Stipulates the basic principles of time retrospection; must follow the principle of observation first, then limited intervention</td></tr><tr><td>Article 50</td><td>Stipulates that the right to interpret the Constitution belongs to the Symbiosis Court, and the right to amend the Constitution belongs to the Anker Council</td></tr></tbody></table><h2 id="iii-symbiosis-labor-law" tabindex="-1">III. Symbiosis Labor Law <a class="header-anchor" href="#iii-symbiosis-labor-law" aria-label="Permalink to &quot;III. Symbiosis Labor Law&quot;">​</a></h2><p>The &quot;Symbiosis Labor Law&quot; is the basic law regulating labor relations and protecting workers&#39; rights and interests, based on Article 42 of the Symbiosis Constitution as the legislative basis.</p><table tabindex="0"><thead><tr><th>Provision Number</th><th>Core Content</th></tr></thead><tbody><tr><td>Article 1</td><td>Legislative purpose: regulate labor relations, protect the legitimate rights and interests of workers, and build harmonious and symbiotic labor relations</td></tr><tr><td>Article 2</td><td>Scope of application: all labor relations within Hengyuanzhou, including material labor, cultivation labor, and creative labor</td></tr><tr><td>Article 3</td><td>Establishes the principle of equal employment for workers; prohibits employment discrimination based on race, gender, cultivation level, or origin</td></tr><tr><td>Article 4</td><td>Establishes the principle of free choice of occupation for workers; prohibits forced labor and slavery</td></tr><tr><td>Article 5</td><td>Stipulates the labor contract system; a written labor contract shall be concluded when establishing a labor relationship</td></tr><tr><td>Article 6</td><td>Stipulates the necessary clauses of a labor contract: contract term, work content, labor remuneration, working hours, labor protection, social insurance</td></tr><tr><td>Article 7</td><td>Establishes the eight-hour work system and the working hour system of no more than forty-four hours per week</td></tr><tr><td>Article 8</td><td>Stipulates overtime restrictions: daily overtime shall not exceed one hour, special circumstances shall not exceed three hours, monthly overtime shall not exceed thirty-six hours</td></tr><tr><td>Article 9</td><td>Stipulates overtime wage standards: 1.5 times wages for working day overtime, 2 times wages for rest day overtime, 3 times wages for statutory holiday overtime</td></tr><tr><td>Article 10</td><td>Establishes the minimum wage guarantee system; minimum wage standards are formulated by each star domain according to local conditions</td></tr><tr><td>Article 11</td><td>Stipulates the wage payment system: wages shall be paid monthly to the workers themselves in monetary form, and shall not be deducted or defaulted without reason</td></tr><tr><td>Article 12</td><td>Establishes the distribution principle of more work more gain; implements a distribution system with distribution according to work as the main body and multiple distribution methods coexisting</td></tr><tr><td>Article 13</td><td>Stipulates the labor safety and health system; employers must provide workers with labor safety and health conditions that meet standards</td></tr><tr><td>Article 14</td><td>Stipulates special group protection: special labor protection for minor workers, female workers, disabled workers, and low-cultivation workers</td></tr><tr><td>Article 15</td><td>Establishes the vocational training system; employers have the obligation to conduct vocational skills training for workers</td></tr><tr><td>Article 16</td><td>Stipulates the labor rights and interests of cultivators: cultivation labor is also protected by this law; the ownership of cultivation results is agreed upon by contract</td></tr><tr><td>Article 17</td><td>Establishes the workers&#39; social insurance system: pension insurance, medical insurance, unemployment insurance, work-related injury insurance, maternity insurance</td></tr><tr><td>Article 18</td><td>Stipulates the workers&#39; welfare system: employers shall provide necessary welfare benefits for workers</td></tr><tr><td>Article 19</td><td>Establishes the labor dispute handling system: four-level handling mechanism of negotiation, mediation, arbitration, and litigation</td></tr><tr><td>Article 20</td><td>Stipulates the trade union system; workers have the right to organize and join trade unions according to law to safeguard their legitimate rights and interests</td></tr><tr><td>Article 21</td><td>Stipulates the collective contract system; trade unions represent employees in concluding collective contracts with employers</td></tr><tr><td>Article 22</td><td>Stipulates that the rules and regulations of employers shall be discussed by the employee representative congress or all employees</td></tr><tr><td>Article 23</td><td>Stipulates the conditions and procedures for terminating labor contracts</td></tr><tr><td>Article 24</td><td>Stipulates the economic compensation system; employers shall pay economic compensation when terminating labor contracts according to law</td></tr><tr><td>Article 25</td><td>Stipulates the compensation system for illegal termination of labor contracts</td></tr><tr><td>Article 26</td><td>Establishes the labor dispatch management system, regulating labor dispatch employment</td></tr><tr><td>Article 27</td><td>Stipulates special rules for part-time employment</td></tr><tr><td>Article 28</td><td>Stipulates the supervision and inspection system; labor administrative departments supervise and inspect employers&#39; compliance with labor laws and regulations according to law</td></tr><tr><td>Article 29</td><td>Stipulates legal liabilities: employers who violate this law shall bear administrative, civil, and criminal liabilities according to law</td></tr><tr><td>Article 30</td><td>Stipulates the effective date and interpretation right of this law</td></tr></tbody></table><h2 id="iv-consumer-protection-law" tabindex="-1">IV. Consumer Protection Law <a class="header-anchor" href="#iv-consumer-protection-law" aria-label="Permalink to &quot;IV. Consumer Protection Law&quot;">​</a></h2><p>The &quot;Consumer Protection Law&quot; is the basic law protecting consumers&#39; legitimate rights and interests and regulating business operators&#39; behavior.</p><table tabindex="0"><thead><tr><th>Provision Number</th><th>Core Content</th></tr></thead><tbody><tr><td>Article 1</td><td>Legislative purpose: protect consumers&#39; legitimate rights and interests, maintain social and economic order, and promote the healthy development of the symbiotic market economy</td></tr><tr><td>Article 2</td><td>Scope of application: protection of rights and interests of consumers within Hengyuanzhou who purchase, use goods, or accept services for daily consumption needs</td></tr><tr><td>Article 3</td><td>Establishes the basic principles of transactions between business operators and consumers: voluntariness, equality, fairness, honesty and credit</td></tr><tr><td>Article 4</td><td>Establishes the principle of state protection of consumers&#39; legitimate rights and interests; the state takes measures to ensure consumers exercise their rights according to law</td></tr><tr><td>Article 5</td><td>Stipulates nine basic rights of consumers: right to safety, right to know, right to independent choice, right to fair trade, right to claim compensation, right to association, right to acquire knowledge, right to be respected, right to supervision</td></tr><tr><td>Article 6</td><td>Stipulates consumers&#39; right to safety: consumers enjoy the right to personal and property safety not being damaged when purchasing, using goods, and accepting services</td></tr><tr><td>Article 7</td><td>Stipulates consumers&#39; right to know: consumers enjoy the right to know the true situation of the goods they purchase or use or the services they accept</td></tr><tr><td>Article 8</td><td>Stipulates consumers&#39; right to independent choice: consumers enjoy the right to independently choose goods or services</td></tr><tr><td>Article 9</td><td>Stipulates consumers&#39; right to fair trade: consumers enjoy the right to fair trade and have the right to refuse forced trading behavior</td></tr><tr><td>Article 10</td><td>Stipulates consumers&#39; right to claim compensation: consumers who suffer personal or property damage due to purchasing, using goods, or accepting services enjoy the right to obtain compensation according to law</td></tr><tr><td>Article 11</td><td>Stipulates basic obligations of business operators: perform statutory and contractual obligations, accept supervision, ensure safety, provide true information, issue vouchers, guarantee quality, perform three guarantees, shall not conduct unfair trade, shall not infringe personality</td></tr><tr><td>Article 12</td><td>Stipulates business operators&#39; safety guarantee obligation: business operators shall ensure that the goods or services they provide meet the requirements of protecting personal and property safety</td></tr><tr><td>Article 13</td><td>Stipulates business operators&#39; information disclosure obligation: business operators shall provide consumers with true information about goods or services, and shall not make false or misleading publicity</td></tr><tr><td>Article 14</td><td>Stipulates special norms for cultivation products and services: business operators of cultivation methods, cultivation instruments, and energy products must have special qualifications, and products must pass safety certification</td></tr><tr><td>Article 15</td><td>Stipulates the regulation of standard clauses: business operators shall not exclude or limit consumers&#39; rights, reduce or exempt business operators&#39; liabilities through standard clauses</td></tr><tr><td>Article 16</td><td>Stipulates the seven-day no-reason return system: consumers who purchase goods through remote methods such as the Internet have the right to return goods within seven days from the date of receiving the goods</td></tr><tr><td>Article 17</td><td>Stipulates the three-guarantee system: if the goods or services provided by business operators do not meet quality requirements, consumers may require repair, replacement, or return according to state regulations</td></tr><tr><td>Article 18</td><td>Stipulates the punitive compensation system: if business operators have fraudulent behavior in providing goods or services, they shall increase compensation for the losses suffered by consumers according to consumers&#39; requirements, and the increased compensation amount shall be three times the price of goods purchased by consumers or the cost of services accepted</td></tr><tr><td>Article 19</td><td>Stipulates consumer organizations: consumer associations and other consumer organizations are social organizations established according to law that conduct social supervision of goods and services to protect consumers&#39; legitimate rights and interests</td></tr><tr><td>Article 20</td><td>Stipulates consumer dispute resolution channels: negotiate settlement with business operators, request consumer association mediation, appeal to relevant administrative departments, apply for arbitration, file a lawsuit with the court</td></tr><tr><td>Article 21</td><td>Stipulates the reversal of the burden of proof in disputes: for durable goods or services such as decoration, if consumers find defects within six months from the date of acceptance, the business operator shall bear the burden of proof</td></tr><tr><td>Article 22</td><td>Stipulates the administrative and criminal liabilities of business operators</td></tr><tr><td>Article 23</td><td>Stipulates the effective date and interpretation right of this law</td></tr></tbody></table><h2 id="v-five-supporting-laws" tabindex="-1">V. Five Supporting Laws <a class="header-anchor" href="#v-five-supporting-laws" aria-label="Permalink to &quot;V. Five Supporting Laws&quot;">​</a></h2><h3 id="_5-1-education-security-law" tabindex="-1">5.1 Education Security Law <a class="header-anchor" href="#_5-1-education-security-law" aria-label="Permalink to &quot;5.1 Education Security Law&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Provision Number</th><th>Core Content</th></tr></thead><tbody><tr><td>Article 1</td><td>Legislative purpose: guarantee all sentient beings&#39; equal right to education, build a symbiotic education system, and promote the common development of all races&#39; cultures</td></tr><tr><td>Articles 2-5</td><td>Establish the education equity principle, education free principle (basic education stage), education diversity principle, education innovation principle</td></tr><tr><td>Articles 6-10</td><td>Stipulate the system architecture of preschool education, compulsory education, high school education, higher education, and cultivation education</td></tr><tr><td>Articles 11-15</td><td>Stipulate special systems for cultivation education: teaching norms for three hundred sets of systems, mentor system, cultivation resource allocation system</td></tr><tr><td>Articles 16-20</td><td>Stipulate teachers&#39; rights and obligations, teacher qualification system, teacher treatment guarantee</td></tr><tr><td>Articles 21-25</td><td>Stipulate education investment guarantee, education facility construction, education informatization, special education, cross-race education</td></tr><tr><td>Articles 26-30</td><td>Stipulate education evaluation system, education supervision system, legal liabilities and supplementary provisions</td></tr></tbody></table><h3 id="_5-2-medical-security-law" tabindex="-1">5.2 Medical Security Law <a class="header-anchor" href="#_5-2-medical-security-law" aria-label="Permalink to &quot;5.2 Medical Security Law&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Provision Number</th><th>Core Content</th></tr></thead><tbody><tr><td>Article 1</td><td>Legislative purpose: establish a universal medical security system, guarantee all sentient beings&#39; right to health, and improve the overall health level of all races</td></tr><tr><td>Articles 2-5</td><td>Establish the universal medical insurance principle, basic medical free principle, integration of Chinese and Western medicine principle, inclusion of cultivation medicine principle</td></tr><tr><td>Articles 6-10</td><td>Stipulate the multi-level medical insurance system of basic medical insurance, serious illness insurance, medical assistance, and commercial health insurance</td></tr><tr><td>Articles 11-15</td><td>Stipulate medical institution management, medical staff system, medical quality and safety, special norms for cultivation medicine</td></tr><tr><td>Articles 16-20</td><td>Stipulate drug management, medical device management, energy medical product management, essential drug system</td></tr><tr><td>Articles 21-25</td><td>Stipulate public health system, disease prevention and control, health education, cross-race medical care, special group medical security</td></tr><tr><td>Articles 26-30</td><td>Stipulate medical dispute handling, medical supervision, legal liabilities and supplementary provisions</td></tr></tbody></table><h3 id="_5-3-housing-security-law" tabindex="-1">5.3 Housing Security Law <a class="header-anchor" href="#_5-3-housing-security-law" aria-label="Permalink to &quot;5.3 Housing Security Law&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Provision Number</th><th>Core Content</th></tr></thead><tbody><tr><td>Article 1</td><td>Legislative purpose: guarantee all sentient beings&#39; basic right to housing, build a multi-level housing security system, and achieve housing for all</td></tr><tr><td>Articles 2-5</td><td>Establish the housing right guarantee principle, housing equity principle, simultaneous rental and purchase principle, sustainable housing principle</td></tr><tr><td>Articles 6-10</td><td>Stipulate the housing supply system of public rental housing, affordable rental housing, shared property housing, and commercial housing</td></tr><tr><td>Articles 11-15</td><td>Stipulate housing provident fund system, housing subsidy system, first home support policy, special housing policy for cultivators</td></tr><tr><td>Articles 16-20</td><td>Stipulate housing construction standards, application of space technology in housing, green buildings, aging-friendly and barrier-free housing</td></tr><tr><td>Articles 21-25</td><td>Stipulate real estate market regulation, housing rental market regulation, property service management, housing maintenance guarantee</td></tr><tr><td>Articles 26-30</td><td>Stipulate housing security supervision, legal liabilities and supplementary provisions</td></tr></tbody></table><h3 id="_5-4-environmental-protection-law" tabindex="-1">5.4 Environmental Protection Law <a class="header-anchor" href="#_5-4-environmental-protection-law" aria-label="Permalink to &quot;5.4 Environmental Protection Law&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Provision Number</th><th>Core Content</th></tr></thead><tbody><tr><td>Article 1</td><td>Legislative purpose: protect and improve the environment, prevent and control pollution and other public hazards, guarantee public health, promote the construction of cosmic ecological civilization, and promote sustainable development</td></tr><tr><td>Articles 2-5</td><td>Establish the protection priority principle, prevention first principle, comprehensive governance principle, public participation principle, damage responsibility principle</td></tr><tr><td>Articles 6-10</td><td>Stipulate environmental supervision and management system, environmental standard system, environmental impact assessment system, environmental monitoring system, cross-plane environmental management</td></tr><tr><td>Articles 11-15</td><td>Stipulate air pollution prevention and control, water pollution prevention and control, soil pollution prevention and control, energy pollution prevention and control, law pollution prevention and control</td></tr><tr><td>Articles 16-20</td><td>Stipulate solid waste treatment, noise pollution prevention and control, radioactive pollution prevention and control, ecological protection, biodiversity protection</td></tr><tr><td>Articles 21-25</td><td>Stipulate environmental impact control of cultivation activities, ecological protection of energy mining, environmental requirements for cross-plane archaeology</td></tr><tr><td>Articles 26-30</td><td>Stipulate information disclosure and public participation, environmental public interest litigation, legal liabilities and supplementary provisions</td></tr></tbody></table><h3 id="_5-5-antitrust-law" tabindex="-1">5.5 Antitrust Law <a class="header-anchor" href="#_5-5-antitrust-law" aria-label="Permalink to &quot;5.5 Antitrust Law&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Provision Number</th><th>Core Content</th></tr></thead><tbody><tr><td>Article 1</td><td>Legislative purpose: prevent and stop monopolistic behavior, protect fair market competition, improve economic operation efficiency, safeguard consumers&#39; interests and social public interests, and promote the healthy development of the symbiotic market economy</td></tr><tr><td>Articles 2-5</td><td>Establish the basic position of competition policy, fair competition review system, prohibition of monopoly agreements, prohibition of abuse of market dominant position, control of business concentration</td></tr><tr><td>Articles 6-10</td><td>Stipulate the identification and exemption of monopoly agreements, horizontal monopoly agreements, vertical monopoly agreements, monopolistic behavior of industry associations</td></tr><tr><td>Articles 11-15</td><td>Stipulate the identification of market dominant position, behavior types of abuse of market dominant position, prohibition of predatory pricing</td></tr><tr><td>Articles 16-20</td><td>Stipulate business concentration declaration standards, review procedures, additional restrictive conditions, decisions prohibiting concentration</td></tr><tr><td>Articles 21-25</td><td>Stipulate special prohibition of cultivation system monopoly: prohibition of monopolizing cultivation methods, prohibition of cultivation resource monopoly, prohibition of mentor network monopoly</td></tr><tr><td>Articles 26-30</td><td>Stipulate antitrust law enforcement agencies, investigation procedures, legal liabilities, leniency system and supplementary provisions</td></tr></tbody></table><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>The index of legal provisions is a reference map of the rule of law system of the Anker Symbiosis Civilization. From the Symbiosis Constitution as the fundamental law, to the Labor Law and Consumer Protection Law regulating people&#39;s livelihood, and then to the five supporting laws, they together constitute a complete legal system &quot;with the Constitution as the commander, basic laws as the backbone, and supporting laws as the support&quot;. This system ensures that all activities of the symbiosis civilization operate on the track of the rule of law, providing a solid institutional guarantee for the common progress of all races.</p><h2 id="related-documents" tabindex="-1">Related Documents <a class="header-anchor" href="#related-documents" aria-label="Permalink to &quot;Related Documents&quot;">​</a></h2><ul><li>40-Symbiosis Constitution General Outline</li><li>41-Symbiosis Labor Law</li><li>48-Judicial System and Adjudication Mechanism</li></ul>',28)])])}const m=e(a,[["render",s]]);export{p as __pageData,m as default};
